/* The tables of M07 · Students. */

/** A household. Siblings share one family, which is what sibling discounts and family billing use. */
export const families = defineTable(
  'families',
  { module: 'M07', scope: 'org', household: true, householdColumn: 'id' },
  {
    ...baseColumns,
    /** from the `family` sequence */
    familyCode: text().notNull(),
    /** optional until the first guardian is added */
    primaryGuardianId: uuid().references((): AnyPgColumn => guardians.id),
    address: text(),
    city: text(),
    homePhone: text(),
    /** used by advance tax on fees */
    isTaxFiler: boolean().notNull().default(false),
    incomeBand: enumText(familyIncomeBands).notNull().default('not_stated'),
    notes: text(),
  },
  (t) => [uniqueIndex('families_family_code_uq').on(t.orgId, t.familyCode).where(live(t))],
);

export const guardians = defineTable(
  'guardians',
  { module: 'M07', scope: 'org', guardian: 'id' },
  {
    ...baseColumns,
    familyId: uuid()
      .references((): AnyPgColumn => families.id)
      .notNull(),
    fullName: text().notNull(),
    fullNameUr: text(),
    /** sensitive */
    cnic: text(),
    /** E.164 */
    phone: text().notNull(),
    /** defaults to `phone` */
    whatsappPhone: text(),
    phoneAlt: text(),
    email: text(),
    occupation: text(),
    employer: text(),
    education: text(),
    isDeceased: boolean().notNull().default(false),
    photoFileId: uuid().references((): AnyPgColumn => files.id),
    preferredLocale: enumText(locales).notNull().default('ur'),
    custom: jsonb().notNull().default({}),
  },
  (t) => [
    uniqueIndex('guardians_cnic_uq')
      .on(t.orgId, t.cnic)
      .where(sql`${t.deletedAt} is null and ${t.cnic} is not null`),
    index('guardians_phone_idx').on(t.orgId, t.phone),
    index('guardians_full_name_trgm').using('gin', sql`${t.fullName} gin_trgm_ops`),
  ],
);

export const students = defineTable(
  'students',
  { module: 'M07', scope: 'branch', family: 'id' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    familyId: uuid()
      .references((): AnyPgColumn => families.id)
      .notNull(),
    /** from the `admission` sequence */
    admissionNo: text().notNull(),
    fullName: text().notNull(),
    fullNameUr: text(),
    fatherName: text().notNull(),
    gender: enumText(studentGenders).notNull(),
    /** not in the future */
    dateOfBirth: dateStr().notNull(),
    placeOfBirth: text(),
    /** sensitive; 13 digits with dashes */
    bFormNo: text(),
    /** decides Islamiyat or Ethics */
    religion: enumText(religions).notNull().default('islam'),
    motherTongue: text(),
    bloodGroup: enumText(bloodGroups).notNull().default('unknown'),
    photoFileId: uuid().references((): AnyPgColumn => files.id),
    /** the student's own */
    phone: text(),
    /** when different from the family's */
    address: text(),
    previousSchool: text(),
    previousClass: text(),
    admittedOn: dateStr().notNull(),
    admissionGradeId: uuid()
      .references((): AnyPgColumn => grades.id)
      .notNull(),
    status: enumText(studentStatuses).notNull().default('active'),
    /** required once status is left, transferred, graduated or expelled */
    leftOn: dateStr(),
    leavingReason: text(),
    houseId: uuid().references((): AnyPgColumn => houses.id),
    isOrphan: boolean().notNull().default(false),
    /** marks a staff child */
    staffParentId: uuid().references((): AnyPgColumn => staff.id),
    /** one line teachers always see (asthma, nut allergy) */
    medicalAlert: text(),
    specialNeeds: text(),
    boardRegistrationNo: text(),
    sourceApplicationId: uuid().references((): AnyPgColumn => admissionApplications.id),
    custom: jsonb().notNull().default({}),
  },
  (t) => [
    check(
      'students_left_on_needed',
      sql`${t.status} not in ('left', 'transferred', 'graduated', 'expelled') or ${t.leftOn} is not null`,
    ),
    uniqueIndex('students_admission_no_uq').on(t.orgId, t.admissionNo).where(live(t)),
    uniqueIndex('students_b_form_no_uq')
      .on(t.orgId, t.bFormNo)
      .where(sql`${t.deletedAt} is null and ${t.bFormNo} is not null`),
    index('students_branch_status_idx').on(t.orgId, t.branchId, t.status),
    index('students_family_idx').on(t.orgId, t.familyId),
    index('students_full_name_trgm').using('gin', sql`${t.fullName} gin_trgm_ops`),
    index('students_father_name_trgm').using('gin', sql`${t.fatherName} gin_trgm_ops`),
    index('students_admission_no_trgm').using('gin', sql`${t.admissionNo} gin_trgm_ops`),
  ],
);

export const studentGuardians = defineTable(
  'student_guardians',
  { module: 'M07', scope: 'org', family: 'studentId' },
  {
    ...baseColumns,
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    guardianId: uuid()
      .references((): AnyPgColumn => guardians.id)
      .notNull(),
    relation: enumText(studentGuardianRelations).notNull(),
    isPrimary: boolean().notNull().default(false),
    canPickup: boolean().notNull().default(true),
    receivesMessages: boolean().notNull().default(true),
    isEmergencyContact: boolean().notNull().default(false),
    livesWithStudent: boolean().notNull().default(true),
  },
  (t) => [
    uniqueIndex('student_guardians_student_guardian_uq')
      .on(t.studentId, t.guardianId)
      .where(live(t)),
    uniqueIndex('student_guardians_primary_uq')
      .on(t.studentId)
      .where(sql`${t.isPrimary} and ${t.deletedAt} is null`),
  ],
);

/** One row per student per academic year: which class they sit in. */
export const enrollments = defineTable(
  'enrollments',
  { module: 'M07', scope: 'branch', family: 'studentId' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    academicYearId: uuid()
      .references((): AnyPgColumn => academicYears.id)
      .notNull(),
    gradeId: uuid()
      .references((): AnyPgColumn => grades.id)
      .notNull(),
    sectionId: uuid()
      .references((): AnyPgColumn => sections.id)
      .notNull(),
    rollNo: integer(),
    /** Grades 9 and 10 */
    subjectGroupId: uuid().references((): AnyPgColumn => subjectGroups.id),
    status: enumText(enrollmentStatuses).notNull().default('active'),
    joinedOn: dateStr().notNull(),
    leftOn: dateStr(),
    outcomeNote: text(),
  },
  (t) => [
    positive('enrollments', t.rollNo),
    uniqueIndex('enrollments_student_academic_year_uq')
      .on(t.orgId, t.studentId, t.academicYearId)
      .where(sql`${t.deletedAt} is null and ${t.status} not in ('left', 'transferred')`),
    uniqueIndex('enrollments_section_roll_no_uq')
      .on(t.sectionId, t.rollNo)
      .where(sql`${t.deletedAt} is null and ${t.status} = 'active'`),
    index('enrollments_section_status_idx').on(t.orgId, t.sectionId, t.status),
  ],
);

