export const promotionItems = defineTable(
  'promotion_items',
  { module: 'M07', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    batchId: uuid()
      .references((): AnyPgColumn => promotionBatches.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    enrollmentId: uuid()
      .references((): AnyPgColumn => enrollments.id)
      .notNull(),
    decision: enumText(promotionItemDecisions).notNull(),
    /** from the promotion rules */
    suggestedDecision: enumText(promotionItemSuggestedDecisions).notNull(),
    toGradeId: uuid().references((): AnyPgColumn => grades.id),
    toSectionId: uuid().references((): AnyPgColumn => sections.id),
    /** required when the decision differs from the suggestion */
    reason: text(),
    /** set on commit */
    newEnrollmentId: uuid().references((): AnyPgColumn => enrollments.id),
    status: enumText(promotionItemStatuses).notNull().default('pending'),
    error: text(),
  },
  (t) => [
    check(
      'promotion_items_reason_needed',
      sql`${t.decision} = ${t.suggestedDecision} or ${t.reason} is not null`,
    ),
    uniqueIndex('promotion_items_batch_student_uq').on(t.batchId, t.studentId).where(live(t)),
  ],
);

/** Moving a student from one branch to another. */
export const transferRequests = defineTable(
  'transfer_requests',
  { module: 'M07', scope: 'org' },
  {
    ...baseColumns,
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    fromBranchId: uuid()
      .references((): AnyPgColumn => branches.id)
      .notNull(),
    /** different from `from_branch_id` */
    toBranchId: uuid()
      .references((): AnyPgColumn => branches.id)
      .notNull(),
    /** optional until approved */
    toSectionId: uuid().references((): AnyPgColumn => sections.id),
    effectiveOn: dateStr().notNull(),
    reason: text().notNull(),
    status: enumText(transferRequestStatuses).notNull().default('requested'),
    decidedBy: uuid().references((): AnyPgColumn => profiles.id),
    decidedAt: timestamptz(),
    decisionNote: text(),
  },
  (t) => [
    check('transfer_requests_to_branch_id_differs', sql`${t.toBranchId} <> ${t.fromBranchId}`),
    uniqueIndex('transfer_requests_student_uq')
      .on(t.orgId, t.studentId)
      .where(sql`${t.deletedAt} is null and ${t.status} in ('requested', 'approved')`),
  ],
);

export const studentWithdrawals = defineTable(
  'student_withdrawals',
  { module: 'M07', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    requestedOn: dateStr().notNull(),
    lastAttendanceOn: dateStr().notNull(),
    reason: enumText(studentWithdrawalReasons).notNull(),
    detail: text(),
    status: enumText(studentWithdrawalStatuses).notNull().default('requested'),
    /** `{ fees, library, inventory, transport, hostel }` each `pending`, `clear` or `waived` */
    clearance: jsonb().notNull().default({}),
    /** snapshot at approval */
    duesOutstanding: paisa().notNull().default(0),
    securityRefund: paisa().notNull().default(0),
    approvedBy: uuid().references((): AnyPgColumn => profiles.id),
    completedAt: timestamptz(),
  },
  (t) => [
    nonNegative('student_withdrawals', t.duesOutstanding),
    nonNegative('student_withdrawals', t.securityRefund),
    uniqueIndex('student_withdrawals_student_uq')
      .on(t.orgId, t.studentId)
      .where(sql`${t.deletedAt} is null and ${t.status} in ('requested', 'clearance', 'approved')`),
  ],
);

/** A guardian asks for a correction; staff decide. */
export const profileChangeRequests = defineTable(
  'profile_change_requests',
  {
    module: 'M07',
    scope: 'org',
    family: 'studentId',
    familyRule: 'append',
    guardian: 'guardianId',
    guardianRule: 'append',
  },
  {
    ...baseColumns,
    studentId: uuid().references((): AnyPgColumn => students.id),
    /** one of the two is required */
    guardianId: uuid().references((): AnyPgColumn => guardians.id),
    /** `{ field: newValue }`, only fields on the allowed list */
    changes: jsonb().notNull(),
    note: text(),
    status: enumText(profileChangeRequestStatuses).notNull().default('pending'),
    decidedBy: uuid().references((): AnyPgColumn => profiles.id),
    decisionNote: text(),
  },
  (t) => [
    check(
      'profile_change_requests_guardian_id_about',
      sql`num_nonnulls(${t.studentId}, ${t.guardianId}) >= 1`,
    ),
  ],
);
